class PaymentProcessorFactory:
    @staticmethod
    def create_processor(payment_type: str, security_code: str):
        if payment_type == 'debit':
            return DebitPaymentProcessor(security_code)
        elif payment_type == 'credit':
            return CreditPaymentProcessor(security_code)
        elif payment_type == 'paypal':
            return PaypalPaymentProcessor(security_code)
        raise Exception('Unknown payment type')

def pay(self, order):
        processor = PaymentProcessorFactory.create_processor('debit', self.security_code)
        processor.pay(order)

